let photoCopyCounter=0;

async function keepPhotoOnDevice(uri:string,index:number) {
  const folder=FileSystem.documentDirectory;
  if(!folder||uri.startsWith(folder))return uri;
  try{const extension=(uri.split('?')[0].split('.').pop()||'jpg').toLowerCase();const safeExtension=/^[a-z0-9]{2,5}$/.test(extension)?extension:'jpg';const destination=`${folder}inframap-photo-${Date.now()}-${photoCopyCounter++}-${index}.${safeExtension}`;await FileSystem.copyAsync({from:uri,to:destination});return destination;}catch{return uri;}
}

