  const [materialLocation,setMaterialLocation]=useState('Hyderabad');
  const [materialMapMode,setMaterialMapMode]=useState(false);
  const [supplierMode,setSupplierMode]=useState(false);
  const [materialFormOpen,setMaterialFormOpen]=useState(false);
  const [buildArea,setBuildArea]=useState('1800');
  const [buildQuality,setBuildQuality]=useState<'Basic'|'Standard'|'Premium'>('Standard');
  const [notices, setNotices] = useState<Notice[]>([]);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [editingId, setEditingId] = useState<string|null>(null);
  const [postStep, setPostStep] = useState(1);
  const [postDraft, setPostDraft] = useState({intent:'Buy' as Intent,type:'Plots',title:'',price:'',area:'',builtArea:'',dimensions:'',facing:'East',roadWidth:'',beds:'',baths:'',parking:'',city:'Hyderabad',locality:'',latitude:'',longitude:'',accuracy:'',capturedAt:'',address:'',locationVisibility:'Approximate public location',boundaryCoordinates:'',surveyNumber:'',plotNumber:'',verificationStatus:'Location Submitted',description:'',ownerName:'',phone:'',ownerType:'Owner' as 'Owner'|'Agent'});
  const [postPhotos, setPostPhotos] = useState<string[]>([]);
  const [postDocuments, setPostDocuments] = useState<string[]>([]);
  const [listMode, setListMode] = useState(false);
  const [satellite, setSatellite] = useState(false);
  const mapRef = useRef<MapView>(null);
  const [mapRegion, setMapRegion] = useState<Region>({ latitude:17.385, longitude:78.4867, latitudeDelta:0.28, longitudeDelta:0.28 });
  const [locationEnabled,setLocationEnabled]=useState(false);
  const [locating,setLocating]=useState(false);
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [selected, setSelected] = useState<Property | null>(null);
  const [detail, setDetail] = useState<Property | null>(null);
  useEffect(()=>{
    (async()=>{try{const saved=await AsyncStorage.getItem(STORAGE_KEY);if(saved){const data=JSON.parse(saved);if(Array.isArray(data.posted)){const restored=await Promise.all(data.posted.map(async(p:Property)=>({...p,photos:await Promise.all((p.photos??[]).map((uri,i)=>keepPhotoOnDevice(uri,i)))})));setPosted(restored);}if(Array.isArray(data.favorites))setFavorites(new Set(data.favorites));if(['Buyer','Owner','Agent','Contractor'].includes(data.demoRole))setDemoRole(data.demoRole);if(Array.isArray(data.enquiries))setEnquiries(data.enquiries);if(Array.isArray(data.myProviders))setMyProviders(data.myProviders);if(Array.isArray(data.serviceRequests))setServiceRequests(data.serviceRequests);if(Array.isArray(data.myMaterialOffers)){const restored=await Promise.all(data.myMaterialOffers.map(async(o:MaterialOffer,i:number)=>({...o,shopPhoto:o.shopPhoto?await keepPhotoOnDevice(o.shopPhoto,i):undefined})));setMyMaterialOffers(restored);}if(Array.isArray(data.materialRequests))setMaterialRequests(data.materialRequests);if(Array.isArray(data.notices))setNotices(data.notices);}}catch{Alert.alert('Local data','Saved demo data could not be read. The app will start with defaults.');}finally{setHydrated(true);}})();
  },[]);
  useEffect(()=>{Location.getForegroundPermissionsAsync().then(permission=>setLocationEnabled(permission.granted)).catch(()=>setLocationEnabled(false));},[]);
  useEffect(()=>{if(!hydrated)return;AsyncStorage.setItem(STORAGE_KEY,JSON.stringify({posted,favorites:[...favorites],demoRole,enquiries,myProviders,serviceRequests,myMaterialOffers,materialRequests,notices})).catch(()=>Alert.alert('Storage full','Could not save the latest local demo changes.'));},[hydrated,posted,favorites,demoRole,enquiries,myProviders,serviceRequests,myMaterialOffers,materialRequests,notices]);
  const choices = intent === 'Buy' ? ['All','Plots','Homes','Apartments','Commercial'] : ['All','Homes','Apartments','Commercial'];
  const allListings = useMemo(() => [...posted.filter(p=>p.published!==false), ...listings], [posted]);
  const results = useMemo(() => allListings.filter(p =>
    p.intent === intent &&
    (category === 'All' || p.type === category) &&
    (!query.trim() || (p.title + ' ' + p.locality + ' ' + p.type + ' ' + p.area + ' Hyderabad').toLowerCase().includes(query.trim().toLowerCase())) &&
    (!minPrice || parsePrice(p.price)>=Number(minPrice)) && (!maxPrice || parsePrice(p.price)<=Number(maxPrice)) &&
    (!bedFilter || (p.beds ?? 0)>=Number(bedFilter)) && (!approvedOnly || p.approved===true)
  ), [allListings, intent, category, query, minPrice, maxPrice, bedFilter, approvedOnly]);
  const everyProperty = useMemo(()=>[...posted,...listings],[posted]);
  const allProviders=useMemo(()=>[...myProviders,...sampleProviders],[myProviders]);
  const serviceResults=useMemo(()=>allProviders.filter(p=>(serviceKind==='All'||p.kind===serviceKind)&&(serviceCategory==='All'||p.category===serviceCategory)&&(!serviceQuery.trim()||`${p.name} ${p.business} ${p.category} ${p.locality}`.toLowerCase().includes(serviceQuery.trim().toLowerCase()))),[allProviders,serviceKind,serviceCategory,serviceQuery]);
  const allMaterialOffers=useMemo(()=>[...myMaterialOffers,...sampleMaterialOffers],[myMaterialOffers]);
  const materialProducts=useMemo(()=>Array.from(new Map(allMaterialOffers.filter(o=>(materialCategory==='All'||o.category===materialCategory)&&(!materialSearch.trim()||`${o.product} ${o.brand} ${o.specification} ${o.category}`.toLowerCase().includes(materialSearch.trim().toLowerCase()))).map(o=>[o.productId,o])).values()),[allMaterialOffers,materialCategory,materialSearch]);
  const compareOffers=useMemo(()=>allMaterialOffers.filter(o=>o.productId===materialProductId),[allMaterialOffers,materialProductId]);
  const areaValue=Math.max(0,Number(buildArea)||0);
  const ratePerSqFt={Basic:1900,Standard:2300,Premium:3000}[buildQuality];
  const buildEstimate=areaValue*ratePerSqFt;
  const buildBoq=useMemo(()=>boqCatalog.map(item=>({item:item.name,unit:item.unit,quantity:Math.ceil(areaValue*item.factor),rate:item.rates[buildQuality],amount:Math.ceil(areaValue*item.factor)*item.rates[buildQuality]})),[areaValue,buildQuality]);
  const exportConstruction=async(format:'pdf'|'xlsx')=>{
    const safeArea=areaValue.toLocaleString('en-IN');
    try {
      if(format==='pdf'){
        const rows=buildBoq.map(x=>`<tr><td>${x.item}</td><td>${x.quantity.toLocaleString('en-IN')} ${x.unit}</td><td>₹${x.rate.toLocaleString('en-IN')}</td><td>₹${x.amount.toLocaleString('en-IN')}</td></tr>`).join('');
        const html=`<html><body style="font-family:Arial,sans-serif;color:#203A47;padding:24px"><h1 style="color:#087E79">InfraMap Construction Estimate</h1><p>Built-up area: ${safeArea} sq ft · Quality: ${buildQuality}</p><h2>Illustrative cost estimate: ₹${buildEstimate.toLocaleString('en-IN')}</h2><p>Rate: ₹${ratePerSqFt.toLocaleString('en-IN')} per sq ft. Sample planning estimate only.</p><h2>Bill of Quantities</h2><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left">Item</th><th align="left">Quantity</th><th align="left">Unit rate</th><th align="left">Amount</th></tr></thead><tbody>${rows}</tbody></table><h3>Indicative BOQ materials total: ₹${buildBoq.reduce((sum,x)=>sum+x.amount,0).toLocaleString('en-IN')}</h3><p style="color:#71858C">Illustrative rates and quantity factors only. Confirm with project drawings, specifications and local suppliers. This is not an engineering-certified BOQ or quotation.</p></body></html>`;
        const file=await Print.printToFileAsync({html});
        if(await Sharing.isAvailableAsync())await Sharing.shareAsync(file.uri,{mimeType:'application/pdf',dialogTitle:'Share construction estimate'});else Alert.alert('PDF created',file.uri);
      } else {
        const workbook=XLSX.utils.book_new();
        const summary=[['InfraMap Construction Estimate'],['Built-up area (sq ft)',areaValue],['Quality',buildQuality],['Illustrative rate per sq ft',ratePerSqFt],['Estimated construction cost',buildEstimate],['BOQ materials total',buildBoq.reduce((sum,x)=>sum+x.amount,0)],['Disclaimer','Illustrative planning estimate; verify quantities and rates before construction.']];
        XLSX.utils.book_append_sheet(workbook,XLSX.utils.aoa_to_sheet(summary),'Estimate');
        XLSX.utils.book_append_sheet(workbook,XLSX.utils.json_to_sheet(buildBoq.map(x=>({'BOQ item':x.item,Quantity:x.quantity,Unit:x.unit,'Unit rate (INR)':x.rate,'Amount (INR)':x.amount}))), 'BOQ');
        const base64=XLSX.write(workbook,{type:'base64',bookType:'xlsx'});
        const uri=`${FileSystem.cacheDirectory??FileSystem.documentDirectory}InfraMap-estimate-${Date.now()}.xlsx`;
        await FileSystem.writeAsStringAsync(uri,base64,{encoding:FileSystem.EncodingType.Base64});
        if(await Sharing.isAvailableAsync())await Sharing.shareAsync(uri,{mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',dialogTitle:'Share Excel BOQ'});else Alert.alert('Excel file created',uri);
      }
    } catch(error){Alert.alert('Export failed',error instanceof Error?error.message:'Could not create the export file.');}
  };
  useEffect(()=>{if(materialProducts.length&&!materialProducts.some(p=>p.productId===materialProductId))setMaterialProductId(materialProducts[0].productId);},[materialProducts,materialProductId]);
  const addNotice=(title:string,message:string)=>setNotices(cur=>[{id:`notice-${Date.now()}`,title,message,createdAt:new Date().toISOString(),read:false},...cur]);
  const createEnquiry=(property:Property)=>{const e:Enquiry={id:`enquiry-${Date.now()}`,propertyId:property.id,title:property.title,price:property.price,locality:property.locality,createdAt:new Date().toISOString(),status:'New'};setEnquiries(cur=>[e,...cur]);addNotice('Enquiry saved',`Your enquiry for ${property.title} is in Enquiries.`);Alert.alert('Enquiry saved','Your local demo enquiry was added to Enquiries.');};
  const saveProvider=(provider:Provider)=>{setMyProviders(cur=>[provider,...cur]);setProviderFormOpen(false);setServiceKind('All');setServiceCategory('All');setServiceQuery('');setTab('Services');setServiceSection('Services');addNotice('Service posted',`${provider.business} was added to your local Services directory.`);Alert.alert('Service posted','Your demo service listing was saved on this device.');};
  const requestProvider=(provider:Provider,requestType:ServiceRequest['requestType'])=>{const request:ServiceRequest={id:`service-${Date.now()}`,providerId:provider.id,providerName:provider.business,category:provider.category,requestType,createdAt:new Date().toISOString(),status:'Requested'};setServiceRequests(cur=>[request,...cur]);addNotice(`${requestType} requested`,`${provider.business} · ${provider.category}`);setProviderDetail(null);Alert.alert(`${requestType} saved`,'Your local demo request is now in Enquiries.');};
  const saveMaterialOffer=async(offer:MaterialOffer)=>{const stored={...offer,shopPhoto:offer.shopPhoto?await keepPhotoOnDevice(offer.shopPhoto,0):undefined};setMyMaterialOffers(cur=>[stored,...cur]);setMaterialCategory(stored.category);setMaterialProductId(stored.productId);setSupplierMode(true);setMaterialFormOpen(false);addNotice('Supplier product added',`${stored.product} was added to your local supplier dashboard.`);Alert.alert('Product listed','Your local demo supplier listing is saved on this device.');};
  const requestMaterialQuotes=(offers:MaterialOffer[])=>{if(!offers.length)return;const quantity=Math.max(1,Number(materialQty)||1);const created=offers.map(o=>({id:`material-request-${Date.now()}-${o.id}`,offerId:o.id,supplier:o.supplier,product:o.product,quantity,createdAt:new Date().toISOString(),status:'Requested' as const}));setMaterialRequests(cur=>[...created,...cur]);addNotice('Material quote requested',`${offers.length} supplier${offers.length===1?'':'s'} · ${quantity} ${offers[0].unit} of ${offers[0].product}`);Alert.alert('Quote request saved',`Your local request for ${quantity} ${offers[0].unit} was saved.`);};
  const savePost = () => {
    const boundary=decodeCoordinates(postDraft.boundaryCoordinates);
    const enteredPin=postDraft.latitude&&postDraft.longitude?{latitude:Number(postDraft.latitude),longitude:Number(postDraft.longitude)}:null;
    const location=boundary.length>=3?(enteredPin&&pointInPolygon(enteredPin,boundary)?enteredPin:polygonCenter(boundary)):enteredPin;
    const p:Property={id:editingId??`local-${Date.now()}`,intent:postDraft.intent,title:postDraft.title,price:postDraft.price,area:postDraft.area||'Not provided',type:postDraft.type,locality:postDraft.locality||'Hyderabad',city:postDraft.city,x:50,y:50,latitude:location?.latitude,longitude:location?.longitude,accuracy:postDraft.accuracy,capturedAt:postDraft.capturedAt,address:postDraft.address,locationVisibility:postDraft.locationVisibility,boundaryCoordinates:postDraft.boundaryCoordinates,surveyNumber:postDraft.surveyNumber,plotNumber:postDraft.plotNumber,verificationStatus:location?'Location Submitted':'Not submitted',beds:postDraft.beds?Number(postDraft.beds):undefined,bathrooms:postDraft.baths?Number(postDraft.baths):undefined,builtArea:postDraft.builtArea,dimensions:postDraft.dimensions,roadWidth:postDraft.roadWidth,parking:postDraft.parking,description:postDraft.description,ownerName:postDraft.ownerName,phone:postDraft.phone,ownerType:postDraft.ownerType,published:true,facing:postDraft.facing,approved:false,photos:postPhotos,documents:postDocuments};
    if(editingId) setPosted(cur=>cur.map(q=>q.id===editingId?p:q)); else setPosted(cur=>[p,...cur]);
    const wasEditing=!!editingId;setEditingId(null);setPostStep(1);setPostDraft({intent:'Buy',type:'Plots',title:'',price:'',area:'',builtArea:'',dimensions:'',facing:'East',roadWidth:'',beds:'',baths:'',parking:'',city:'Hyderabad',locality:'',latitude:'',longitude:'',accuracy:'',capturedAt:'',address:'',locationVisibility:'Approximate public location',boundaryCoordinates:'',surveyNumber:'',plotNumber:'',verificationStatus:'Location Submitted',description:'',ownerName:'',phone:'',ownerType:'Owner'});setPostPhotos([]);setPostDocuments([]);setTab('Profile');if(!wasEditing)addNotice('Listing saved',`${p.title} was added to My listings.`);info(wasEditing?'Listing updated':'Listing saved',wasEditing?'Your local listing changes were saved.':'Your sample property is now available in Explore and My listings.');
  };
  const editPost=(p:Property)=>{setEditingId(p.id);setPostDraft({intent:p.intent,type:p.type,title:p.title,price:p.price,area:p.area,builtArea:p.builtArea??'',dimensions:p.dimensions??'',facing:p.facing??'East',roadWidth:p.roadWidth??'',beds:p.beds?String(p.beds):'',baths:p.bathrooms?String(p.bathrooms):'',parking:p.parking??'',city:p.city??'Hyderabad',locality:p.locality,latitude:p.latitude?String(p.latitude):'',longitude:p.longitude?String(p.longitude):'',accuracy:String(p.accuracy??''),capturedAt:p.capturedAt??'',address:p.address??'',locationVisibility:p.locationVisibility??'Approximate public location',boundaryCoordinates:p.boundaryCoordinates??'',surveyNumber:p.surveyNumber??'',plotNumber:p.plotNumber??'',verificationStatus:p.verificationStatus??'Location Submitted',description:p.description??'',ownerName:p.ownerName??'',phone:p.phone??'',ownerType:p.ownerType??'Owner'});setPostPhotos(p.photos??[]);setPostDocuments(p.documents??[]);setPostStep(1);setTab('Post');};
