    <FiltersModal visible={filterOpen} intent={intent} min={draftMin} max={draftMax} beds={draftBeds} approved={draftApproved} setMin={setDraftMin} setMax={setDraftMax} setBeds={setDraftBeds} setApproved={setDraftApproved} onClose={()=>setFilterOpen(false)} onReset={()=>{setDraftMin('');setDraftMax('');setDraftBeds('');setDraftApproved(false);setMinPrice('');setMaxPrice('');setBedFilter('');setApprovedOnly(false);setFilterOpen(false);}} onApply={()=>{setMinPrice(draftMin);setMaxPrice(draftMax);setBedFilter(draftBeds);setApprovedOnly(draftApproved);setFilterOpen(false);}} />
